const crypto = require('crypto');
const req = $('Normalizar request').first().json;
const auth = String(req.authorization || req.headers?.authorization || req.headers?.Authorization || '');
const secret = String($input.first().json.jwtSecret || '');
const match = auth.match(/^Bearer\s+(.+)$/i);
function fail(message) { return [{ json: { ok: false, statusCode: 401, message } }]; }
if (!match || !secret) return fail('Token ausente ou inválido.');
const token = match[1].trim();
const parts = token.split('.');
if (parts.length !== 3) return fail('JWT malformado.');
const [h, p, s] = parts;
const expected = crypto.createHmac('sha256', secret).update(h + '.' + p).digest('base64url');
const a = Buffer.from(s);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return fail('Assinatura JWT inválida.');
let payload;
try { payload = JSON.parse(Buffer.from(p, 'base64url').toString('utf8')); } catch { return fail('Payload inválido.'); }
const now = Math.floor(Date.now() / 1000);
if (payload.exp && now >= Number(payload.exp)) return fail('Sessão expirada.');
const sessionId = payload.sessionId || payload.sid;
if (!sessionId) return fail('sessionId ausente.');
return [{ json: { ok: true, sessionId: String(sessionId) } }];

