const documentId = $('Preparar texto extraído').first().json.documentId;
const text = $('Preparar texto extraído').first().json.extractedText || '';

const cleanText = text
  .replace(/\s+/g, ' ')
  .trim();

const chunkSize = 1200;
const overlap = 150;

const chunks = [];

for (let i = 0; i < cleanText.length; i += chunkSize - overlap) {
  const content = cleanText.slice(i, i + chunkSize).trim();

  if (content.length > 50) {
    chunks.push({
      json: {
        documentId,
        chunkIndex: chunks.length,
        content
      }
    });
  }
}

return chunks;

