const crypto = require('crypto');
const session = $input.first().json;
const user = $('Buscar usuário').first().json;

function b64url(value) {
  return Buffer.from(value).toString('base64url');
}

const issuedAtSec = Math.floor(new Date(session.issuedAt).getTime() / 1000);
const expiresAtSec = Math.floor(new Date(session.expiresAt).getTime() / 1000);

const header = { alg: 'HS256', typ: 'JWT' };
const payload = {
  sessionId: session.sessionId,
  userId: user.id,
  issuedAt: issuedAtSec,
  expiresAt: expiresAtSec,
  jti: session.tokenId,
  sub: user.id,
  iat: issuedAtSec,
  exp: expiresAtSec,
  iss: 'oftalmocentro-inteligente',
};

const encodedHeader = b64url(JSON.stringify(header));
const encodedPayload = b64url(JSON.stringify(payload));
const data = `${encodedHeader}.${encodedPayload}`;
const signature = crypto
  .createHmac('sha256', String(session.jwtSecret))
  .update(data)
  .digest('base64url');

return [{
  json: {
    token: `${data}.${signature}`,
    expiresAt: session.expiresAt,
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
      sectorId: user.sector_id,
      sectorName: user.sectorName,
      active: user.active,
      isMaster: user.is_master,
      permissions: Array.isArray(user.permissions)
        ? user.permissions.filter((code) => code !== 'gerenciar_tags')
        : [],
    },
  },
}];

